/* Current revision 2 document build, in dependency order. */
require('./refactor-inspections-technical-spec.cjs');
require('./refactor-inspections-build-plan.cjs');
require('./validate-inspections-config-docs.cjs');
// Content reviews are maintained after reading the tasks, never regenerated by this build.
const fs=require('node:fs'),path=require('node:path');
const {validate}=require('./validate-implementation-task-contract.cjs');
const target=path.join('docs','phase 1','inspections','target');
const load=name=>JSON.parse(fs.readFileSync(path.join(target,name),'utf8'));
const review=load('implementation-content-review.json');
const contentReport=validate(load('implementation-plan.json'),fs.readFileSync(path.join(target,'implementation-plan.md'),'utf8'),review,review.reviewKind==='scoped-revision'?review.scope:undefined);
fs.writeFileSync(path.join(target,'implementation-content-validation.json'),JSON.stringify(contentReport,null,2)+'\n');
console.log(JSON.stringify({contentGatePassed:contentReport.passed,scope:contentReport.scope,unreviewedTasks:contentReport.unreviewedTaskIds.length,errors:contentReport.errors},null,2));
if(!contentReport.passed)throw Error('Task content gate failed; review the current task content and resolve implementation-content-validation.json findings.');
